function setInputTab(tab){activeInput=tab;document.querySelectorAll('[data-input-tab]').forEach(b=>b.classList.toggle('active',b.dataset.inputTab===tab));$('svgPanel').hidden=tab!=='svg';$('textPanel').hidden=tab!=='text';}
